"""
apply_foxxdesk_rebrand_from_reference.py

Script autossuficiente gerado a partir do ZIP de referência FoxxDesk-main_6.zip.
Ele NÃO lê o ZIP durante a execução local.

O manifesto interno contém uma lista fechada de arquivos e blocos alterados
comparando os snapshots existentes em .foxxdesk-brand-backup/ com o estado
final do projeto de referência.

Regras de segurança aplicadas:
- não faz substituição global cega;
- só edita arquivos presentes no manifesto interno;
- só troca blocos exatos encontrados no diff da referência;
- se o trecho original não existe e o trecho final também não existe, registra pendência;
- cria backup antes de salvar;
- preserva encoding e quebras de linha sempre que possível;
- não edita arquivos binários;
- não renomeia, não move e não apaga arquivos.
"""
