def load_manifest() -> Dict[str, Any]:
    raw = base64.b64decode("".join(_MANIFEST_B64.split()))
    return json.loads(zlib.decompress(raw).decode("utf-8"))


def die(msg: str, code: int = 2) -> None:
    print(f"ERRO: {msg}", file=sys.stderr)
    raise SystemExit(code)


def normalize_lf(text: str) -> str:
    return text.replace("\r\n", "\n").replace("\r", "\n")


def dominant_newline(text: str) -> str:
    crlf = text.count("\r\n")
    lf = text.count("\n") - crlf
    cr = text.count("\r") - crlf
    if crlf >= lf and crlf >= cr and crlf > 0:
        return "\r\n"
    if cr > lf and cr > 0:
        return "\r"
    return "\n"


def convert_newlines(text: str, newline: str) -> str:
    return normalize_lf(text).replace("\n", newline)


def has_bad_control_chars(text: str) -> bool:
    sample = text[:4096]
    if not sample:
        return False
    bad = 0
    for ch in sample:
        o = ord(ch)
        if ch in "\n\r\t":
            continue
        if o < 32:
            bad += 1
    return (bad / max(1, len(sample))) > 0.03


def decode_file(data: bytes, path: Path) -> Tuple[Optional[str], Optional[str], bool]:
    """Retorna (texto, encoding, is_binary)."""
    suffix = path.suffix.lower()
    if suffix in BINARY_EXTS:
        return None, None, True
    if data.startswith(codecs.BOM_UTF8):
        try:
            return data.decode("utf-8-sig"), "utf-8-sig", False
        except UnicodeDecodeError:
            return None, None, True
    if data.startswith(codecs.BOM_UTF16_LE) or data.startswith(codecs.BOM_UTF16_BE):
        try:
            text = data.decode("utf-16")
            return (text, "utf-16", False) if not has_bad_control_chars(text) else (None, None, True)
        except UnicodeDecodeError:
            return None, None, True
    if b"\x00" in data[:4096]:
        return None, None, True
    for enc in ("utf-8", "cp1252"):
        try:
            text = data.decode(enc)
            if not has_bad_control_chars(text):
                return text, enc, False
        except UnicodeDecodeError:
            pass
    if suffix in TEXT_FALLBACK_EXTS or path.name in {".gitignore", "NOTICE", "LICENSE", "LICENCE"}:
        try:
            text = data.decode("latin-1")
            if not has_bad_control_chars(text):
                return text, "latin-1", False
        except UnicodeDecodeError:
            pass
    return None, None, True


def safe_cli_value(name: str, value: Optional[str]) -> Optional[str]:
    if value is None:
        return None
    value = value.strip()
    if "\n" in value or "\r" in value:
        die(f"{name} não pode conter quebra de linha.")
    return value or None


def redact_value(value: Optional[str], label: str = "valor") -> str:
    if not value:
        return "(não informado)"
    digest = hashlib.sha256(value.encode("utf-8", errors="ignore")).hexdigest()[:10]
    if label == "key":
        return f"<key ocultada; len={len(value)}; sha256={digest}>"
    return value


def redact_text(text: str, args: argparse.Namespace) -> str:
    if args.key:
        text = text.replace(args.key, redact_value(args.key, "key"))
    if REFERENCE_VALUE_KEY in text:
        text = text.replace(REFERENCE_VALUE_KEY, "<reference-key ocultada>")
    return text


def preview(text: str, args: argparse.Namespace, limit: int = 220) -> str:
    text = redact_text(normalize_lf(text).replace("\n", "\\n"), args)
    return text if len(text) <= limit else text[:limit - 3] + "..."


def resolve_new_block(change: Dict[str, Any], args: argparse.Namespace) -> str:
    new = change.get("new", "")
    file = change.get("file", "")
    if REFERENCE_VALUE_SERVER in new:
        if args.relay and file == "FOXXDESK_SERVER_DEFAULTS.md" and "HBBR / Relay" in new:
            new = new.replace(REFERENCE_VALUE_SERVER, args.relay)
        elif args.server:
            new = new.replace(REFERENCE_VALUE_SERVER, args.server)
    if args.key and REFERENCE_VALUE_KEY in new:
        new = new.replace(REFERENCE_VALUE_KEY, args.key)
    if args.maintainer_email:
        new = new.replace(REFERENCE_VALUE_MAINTAINER_EMAIL, args.maintainer_email)
        new = new.replace(REFERENCE_VALUE_MAINTAINER_PLACEHOLDER, args.maintainer_email)
    return new


def find_all(text: str, needle: str) -> List[int]:
    if needle == "":
        return []
    out = []
    start = 0
    while True:
        idx = text.find(needle, start)
        if idx < 0:
            return out
        out.append(idx)
        start = idx + max(1, len(needle))


def locate_with_context(text: str, old: str, before: str, after: str) -> Tuple[Optional[int], Optional[int], str]:
    old = normalize_lf(old)
    before = normalize_lf(before)
    after = normalize_lf(after)
    if old:
        positions = find_all(text, old)
        if len(positions) == 1:
            return positions[0], positions[0] + len(old), "match-exato"
        if len(positions) > 1:
            contextual = []
            for pos in positions:
                ok_before = True if not before else text[:pos].endswith(before)
                ok_after = True if not after else text[pos + len(old):].startswith(after)
                if ok_before and ok_after:
                    contextual.append(pos)
            if len(contextual) == 1:
                pos = contextual[0]
                return pos, pos + len(old), "match-com-contexto"
            return None, None, f"trecho original ambíguo: {len(positions)} ocorrências"
        return None, None, "trecho original não encontrado"

    if before or after:
        token = before + after
        if token and text.count(token) == 1:
            start = text.find(token) + len(before)
            return start, start, "inserção-com-contexto"
        if before and text.count(before) == 1:
            start = text.find(before) + len(before)
            if not after or text[start:].startswith(after):
                return start, start, "inserção-após-contexto"
        if after and text.count(after) == 1:
            start = text.find(after)
            return start, start, "inserção-antes-contexto"
    return None, None, "inserção sem contexto único"


def line_for_pos(text: str, pos: int) -> int:
    return text[:pos].count("\n") + 1


def copy_backup(target: Path, backup_root: Path, rel: str) -> None:
    src = target / rel
    dst = backup_root / rel
    dst.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(src, dst)


def md_escape(s: str) -> str:
    return s.replace("|", "\\|").replace("\n", "\\n")


def apply_file_patches(target: Path, patch: Dict[str, Any], args: argparse.Namespace, backup_root: Optional[Path], report: Dict[str, Any]) -> None:
    rel = patch["file"]
    path = target / rel
    report["analyzed_files"].append(rel)
    if not path.exists():
        report["missing_files"].append(rel)
        return
    if not path.is_file():
        report["pending"].append({"file": rel, "message": "caminho existe, mas não é arquivo"})
        return

    data = path.read_bytes()
    text, encoding, is_binary = decode_file(data, path)
    if is_binary or text is None or encoding is None:
        report["binary_runtime"].append(rel)
        report["ignored_files"].append(rel)
        return

    newline = dominant_newline(text)
    work = normalize_lf(text)
    changed = False
    file_already = True
    file_pending = False

    for change in patch.get("changes", []):
        change = dict(change)
        change["file"] = rel
        old = normalize_lf(change.get("old", ""))
        reference_new = normalize_lf(change.get("new", ""))
        final_new = normalize_lf(resolve_new_block(change, args))
        before = normalize_lf(change.get("before", ""))
        after = normalize_lf(change.get("after", ""))
        cid = change.get("id", f"{rel}:{change.get('old_start')}")

        if final_new and final_new in work:
            report["changes"].append({
                "file": rel, "id": cid, "line": line_for_pos(work, work.find(final_new)),
                "status": "já aplicado", "old": preview(old, args), "new": preview(final_new, args),
                "message": "trecho final já existe"
            })
            continue

        # Alteração de remoção: se o trecho antigo já não existe, está aplicada.
        if final_new == "" and old and old not in work:
            report["changes"].append({
                "file": rel, "id": cid, "line": change.get("old_start"),
                "status": "já aplicado", "old": preview(old, args), "new": "",
                "message": "trecho antigo já ausente"
            })
            continue

        dynamic_reference_update = final_new != reference_new and reference_new and reference_new in work
        if dynamic_reference_update:
            old_for_match = reference_new
            before_for_match = ""
            after_for_match = ""
        else:
            old_for_match = old
            before_for_match = before
            after_for_match = after

        start, end, locate_msg = locate_with_context(work, old_for_match, before_for_match, after_for_match)
        if start is None or end is None:
            if reference_new and reference_new in work:
                report["changes"].append({
                    "file": rel, "id": cid, "line": line_for_pos(work, work.find(reference_new)),
                    "status": "já aplicado", "old": preview(old, args), "new": preview(reference_new, args),
                    "message": "trecho final da referência já existe"
                })
                continue
            file_already = False
            file_pending = True
            report["changes"].append({
                "file": rel, "id": cid, "line": change.get("old_start"),
                "status": "pendente", "old": preview(old, args), "new": preview(final_new, args),
                "message": locate_msg
            })
            report["pending"].append({"file": rel, "change_id": cid, "message": locate_msg})
            continue

        line = line_for_pos(work, start)
        work = work[:start] + final_new + work[end:]
        changed = True
        file_already = False
        report["changes"].append({
            "file": rel, "id": cid, "line": line,
            "status": "alterado" if args.apply else "alteraria",
            "old": preview(old_for_match, args), "new": preview(final_new, args),
            "message": locate_msg + ("; atualização dinâmica" if dynamic_reference_update else "")
        })

    if file_pending:
        report["pending_files"].append(rel)

    if changed:
        report["changed_files"].append(rel)
        if args.apply:
            if backup_root is not None:
                copy_backup(target, backup_root, rel)
            path.write_bytes(convert_newlines(work, newline).encode(encoding, errors="surrogateescape"))
    else:
        if file_already and not file_pending:
            report["already_applied_files"].append(rel)
        else:
            report["ignored_files"].append(rel)


def build_report_md(report: Dict[str, Any], args: argparse.Namespace, manifest: Dict[str, Any]) -> str:
    now = _dt.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    allowed_files = sorted(p["file"] for p in manifest["patches"])
    lines: List[str] = []
    lines.append("# Relatório de rebrand FoxxDesk")
    lines.append("")
    lines.append(f"- Data/hora: `{now}`")
    lines.append(f"- Modo: `{'apply' if args.apply else 'dry-run'}`")
    lines.append(f"- Projeto alvo: `{args.target}`")
    lines.append("- Script: `apply_foxxdesk_rebrand_from_reference.py`")
    lines.append("- ZIP de referência: usado apenas na geração deste script; não é lido em execução.")
    lines.append("")
    lines.append("## Valores dinâmicos usados")
    lines.append("")
    lines.append(f"- server: `{redact_value(args.server)}`")
    lines.append(f"- relay: `{redact_value(args.relay)}`")
    lines.append(f"- key: `{redact_value(args.key, 'key')}`")
    lines.append(f"- maintainer-email: `{redact_value(args.maintainer_email)}`")
    lines.append("")
    lines.append("## Resumo")
    lines.append("")
    lines.append(f"- Total de arquivos autorizados: `{len(allowed_files)}`")
    lines.append(f"- Total de alterações/blocos autorizados: `{sum(len(p.get('changes', [])) for p in manifest['patches'])}`")
    lines.append(f"- Arquivos encontrados/analisados: `{len(set(report['analyzed_files']) - set(report['missing_files']))}`")
    lines.append(f"- Arquivos esperados não encontrados: `{len(set(report['missing_files']))}`")
    lines.append(f"- Arquivos alterados: `{len(set(report['changed_files']))}`")
    lines.append(f"- Arquivos já aplicados: `{len(set(report['already_applied_files']))}`")
    lines.append(f"- Arquivos ignorados: `{len(set(report['ignored_files']))}`")
    lines.append(f"- Pendências: `{len(report['pending'])}`")
    lines.append(f"- Binários/especiais para revisão manual: `{len(manifest.get('binary_or_special_review_files', []))}`")
    if report.get("backup_dir"):
        lines.append(f"- Backup: `{report['backup_dir']}`")
    lines.append("")

    def section(title: str, items: List[str]) -> None:
        lines.append(f"## {title}")
        lines.append("")
        if not items:
            lines.append("Nenhum.")
        else:
            for item in sorted(set(items)):
                lines.append(f"- `{item}`")
        lines.append("")

    section("Arquivos autorizados pelo manifesto interno", allowed_files)
    section("Arquivos analisados", report["analyzed_files"])
    section("Arquivos alterados", report["changed_files"])
    section("Arquivos já aplicados", report["already_applied_files"])
    section("Arquivos ignorados", report["ignored_files"])
    section("Arquivos esperados que não foram encontrados", report["missing_files"])
    section("Arquivos binários ou especiais para revisão manual", manifest.get("binary_or_special_review_files", []))
    section("Arquivos sem snapshot antigo seguro; revisar manualmente", manifest.get("manual_review_files", []))
    section("Binários detectados em runtime e não alterados", report["binary_runtime"])

    lines.append("## Linhas/trechos modificados ou avaliados")
    lines.append("")
    if not report["changes"]:
        lines.append("Nenhuma alteração avaliada.")
    else:
        lines.append("| Status | Arquivo | Linha | ID | Substituição | Mensagem |")
        lines.append("|---|---|---:|---|---|---|")
        for c in report["changes"]:
            subst = f"`{md_escape(c['old'])}` → `{md_escape(c['new'])}`"
            lines.append(
                f"| {c['status']} | `{c['file']}` | {c.get('line') or ''} | `{c['id']}` | {subst} | {md_escape(c.get('message', ''))} |"
            )
    lines.append("")

    lines.append("## Pendências que exigem revisão manual")
    lines.append("")
    if not report["pending"]:
        lines.append("Nenhuma.")
    else:
        for p in report["pending"]:
            cid = p.get("change_id", "")
            msg = p.get("message", "")
            lines.append(f"- `{p.get('file')}` {'[' + cid + ']' if cid else ''}: {msg}")
    lines.append("")

    lines.append("## Erros")
    lines.append("")
    if not report["errors"]:
        lines.append("Nenhum.")
    else:
        for err in report["errors"]:
            lines.append(f"- {err}")
    lines.append("")
    return "\n".join(lines)


def parse_args() -> argparse.Namespace:
    p = argparse.ArgumentParser(
        description="Aplica patches fechados de rebrand RustDesk -> FoxxDesk derivados de um ZIP de referência já analisado."
    )
    p.add_argument("--target", required=True, help="Pasta do projeto alvo.")
    mode = p.add_mutually_exclusive_group(required=True)
    mode.add_argument("--dry-run", action="store_true", help="Mostra o que seria alterado sem salvar.")
    mode.add_argument("--apply", action="store_true", help="Aplica as alterações.")
    p.add_argument("--yes", action="store_true", help="Confirma automaticamente o modo --apply.")
    p.add_argument("--server", default=None, help="Domínio/IP do servidor FoxxDesk, usado só nas linhas equivalentes da referência.")
    p.add_argument("--relay", default=None, help="Domínio/IP do relay FoxxDesk, usado só nas linhas equivalentes da referência.")
    p.add_argument("--key", default=None, help="Chave pública do servidor/rele, usada só nas linhas equivalentes da referência.")
    p.add_argument("--maintainer-email", default=None, help="E-mail do mantenedor, usado só nas linhas equivalentes da referência.")
    return p.parse_args()


def main() -> int:
    args = parse_args()
    args.server = safe_cli_value("--server", args.server)
    args.relay = safe_cli_value("--relay", args.relay)
    args.key = safe_cli_value("--key", args.key)
    args.maintainer_email = safe_cli_value("--maintainer-email", args.maintainer_email)

    target = Path(args.target).expanduser().resolve()
    if not target.exists():
        die(f"--target não existe: {target}")
    if not target.is_dir():
        die(f"--target não é uma pasta: {target}")
    if args.apply and not args.yes:
        resp = input(f"Aplicar alterações em '{target}'? Digite 'SIM' para confirmar: ").strip()
        if resp != "SIM":
            die("aplicação cancelada pelo usuário", code=1)

    manifest = load_manifest()
    backup_root: Optional[Path] = None
    if args.apply:
        stamp = _dt.datetime.now().strftime("%Y%m%d_%H%M%S")
        backup_root = target / ".rebrand_backup" / stamp
        backup_root.mkdir(parents=True, exist_ok=False)

    report: Dict[str, Any] = {
        "analyzed_files": [],
        "missing_files": [],
        "changed_files": [],
        "already_applied_files": [],
        "ignored_files": [],
        "pending_files": [],
        "pending": [],
        "changes": [],
        "binary_runtime": [],
        "errors": [],
        "backup_dir": str(backup_root) if backup_root else "",
    }

    for patch in manifest["patches"]:
        try:
            apply_file_patches(target, patch, args, backup_root, report)
        except Exception as exc:
            rel = patch.get("file", "(desconhecido)")
            report["errors"].append(f"{rel}: {type(exc).__name__}: {exc}")
            report["pending"].append({"file": rel, "message": f"erro durante processamento: {exc}"})

    report_md = build_report_md(report, args, manifest)
    report_path = target / "rebrand_report.md"
    report_path.write_text(report_md, encoding="utf-8", newline="\n")

    changed = len(set(report["changed_files"]))
    pending = len(report["pending"])
    missing = len(set(report["missing_files"]))
    print("Relatório gerado em:", report_path)
    print(f"Modo: {'apply' if args.apply else 'dry-run'} | arquivos alterados: {changed} | pendências: {pending} | não encontrados: {missing}")
    if args.dry_run:
        print("Dry-run concluído: nenhum arquivo do projeto foi salvo, exceto o relatório.")
    return 0 if not report["errors"] else 1


if __name__ == "__main__":
    raise SystemExit(main())
